/bin/zsh -lc "python - <<'PY'
import csv,collections,importlib.util
from decimal import Decimal
with open('inputs/sales.csv',encoding='utf-8-sig',newline='') as f: rows=list(csv.DictReader(f))
print('rows',len(rows),'orders',len(set(r['order_id'] for r in rows)),'unique lines',len(set(r['line_id'] for r in rows)))
for c in rows[0]:
 v=[r[c] for r in rows]; counts=collections.Counter(v)
 if len(counts)<30: print(c,dict(counts))
 elif c.endswith('_at'): print(c,'range',min(x for x in v if x),max(v),'months',dict(collections.Counter(x[:7] for x in v)))
for c in ['line_paid_amount','refund_amount','order_paid_amount','quantity']:
 vals=[Decimal(r[c]) for r in rows if r[c]]; print(c,'sum',sum(vals),'min',min(vals),'max',max(vals))
print('modules',{x:bool(importlib.util.find_spec(x)) for x in ['pandas','matplotlib','numpy','PIL']})
PY"

